begin;

-- student-onboarding-career-readiness-roadmap: HTML shell matches career-readiness-program-launch (00130) / project-completion-nudge (00132); body + text match supplied copy.
update public.email_templates
set
  html_template = $socr143_html$<!DOCTYPE html><html><head><meta charset="utf-8"/><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Your roadmap for {{program_name}}</title></head><body style="margin:0;padding:0;background-color:#F8FAFC;font-family:Arial,Helvetica,sans-serif;color:#111827;-webkit-text-size-adjust:100%;"><div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;color:transparent;opacity:0;">{{email_preheader_text}}</div><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#F8FAFC" style="background-color:#F8FAFC;mso-table-lspace:0;mso-table-rspace:0;"><tr><td align="center" style="padding:24px 12px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#ffffff" style="max-width:680px;background-color:#ffffff;border:1px solid #E5E7EB;border-radius:10px;mso-table-lspace:0;mso-table-rspace:0;"><tr><td bgcolor="#FFFFFF" style="background-color:#FFFFFF;border-bottom:2px solid #F59E0B;padding:22px 24px;"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" bgcolor="#FFFFFF" style="background-color:#FFFFFF;width:100%;mso-table-lspace:0;mso-table-rspace:0;"><tr><td width="52" valign="middle" bgcolor="#FFFFFF" style="background-color:#FFFFFF;padding:0 12px 0 0;vertical-align:middle;"><img src="{{email_logo_url}}" width="48" height="48" alt="NextGen CTO Logo" style="width:48px;height:auto;display:block;border:0;border-radius:8px;outline:none;text-decoration:none;"/></td><td valign="middle" bgcolor="#FFFFFF" style="background-color:#FFFFFF;color:#1E3A8A;font-size:18px;font-weight:800;line-height:1.25;padding:0;vertical-align:middle;">{{email_header_display}}</td></tr></table></td></tr><tr><td bgcolor="#ffffff" style="background-color:#FFFFFF;padding:20px 22px 24px 22px;"><p style="margin:0 0 8px 0;font-size:12px;font-weight:700;color:#F59E0B;text-transform:uppercase;letter-spacing:0.08em;">Student Onboarding</p><h1 style="margin:0 0 10px 0;font-size:26px;line-height:1.25;color:#0F172A;font-weight:800;">Your roadmap for {{program_name}}</h1><table role="presentation" width="100%" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 18px 0;"><tr><td height="2" bgcolor="#F59E0B" style="background-color:#F59E0B;font-size:0;line-height:0;">&nbsp;</td></tr></table><p style="margin:0 0 14px 0;font-size:15px;line-height:1.7;color:#334155;">Hi <strong>{{first_name}}</strong>,</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" style="margin:0 0 22px 0;"><tr><td align="left"><a href="{{cta_url}}" style="display:inline-block;background:linear-gradient(135deg,#e58c33 0%,#d97a1f 100%);color:#FFFFFF;text-decoration:none;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:700;padding:14px 22px;border-radius:50px;box-shadow:0 6px 20px rgba(229,140,51,0.35);letter-spacing:0.5px;">{{cta_label}}</a></td></tr></table><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">Welcome to your career readiness roadmap in {{program_name}}.</p><p style="margin:0 0 12px 0;font-size:15px;line-height:1.7;color:#334155;">You do not need to complete everything in one day.</p><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">The goal is simple:</p><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;">Start step by step and keep moving with clarity.</p><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">Here is how you should approach your journey:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Start with your technical foundations.</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Then move towards AI and modern development basics.</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">After that, focus on hands-on projects.</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Then improve your Resume, GitHub, and LinkedIn.</li><li style="margin:0 0 0px 0;font-size:14px;line-height:1.6;color:#334155;">Finally, prepare yourself for interviews with more confidence.</li></ul><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;">Do not learn randomly.</p><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;">Follow the roadmap, complete your pending steps, and keep checking your progress.</p><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">Your next step is simple:</p><ul style="margin:0 0 18px 0;padding-left:18px;"><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Open your dashboard.</li><li style="margin:0 0 8px 0;font-size:14px;line-height:1.6;color:#334155;">Check your first pending task.</li><li style="margin:0 0 0px 0;font-size:14px;line-height:1.6;color:#334155;">Start from there.</li></ul><p style="margin:0 0 8px 0;font-size:15px;font-weight:700;color:#0F172A;">You can also open your dashboard here:</p><p style="margin:0 0 16px 0;font-size:15px;line-height:1.7;color:#334155;"><a href="{{dashboard_url}}" style="color:#2563EB;text-decoration:underline;">{{dashboard_url}}</a></p><p style="margin:0 0 6px 0;font-size:15px;font-weight:700;color:#0F172A;">If you need help, use the support channel here:</p><p style="margin:0 0 8px 0;font-size:15px;line-height:1.7;color:#334155;"><a href="{{support_url}}" style="color:#F4A854;text-decoration:none;font-weight:600;">{{support_url}}</a></p><p style="margin:0 0 12px 0;font-size:14px;line-height:1.6;color:#64748B;">You are receiving this email because you are a subscriber of NextGen CTO.</p><p style="margin:0;font-size:14px;line-height:1.6;color:#64748B;">Unsubscribe or manage preferences:<br/><a href="{{unsubscribe_url}}" style="color:#64748B;text-decoration:underline;">{{unsubscribe_url}}</a></p></td></tr><tr><td align="center" bgcolor="#ffffff" style="text-align:center;margin-top:50px;font-size:0.9em;color:#777;padding:25px 20px;background:#ffffff;background-color:#ffffff;"><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td valign="middle" style="padding-right:10px;"><a href="{{email_website_url}}" target="_blank" rel="noopener noreferrer" style="text-decoration:none;"><img src="{{email_logo_url}}" alt="NextGen CTO" width="56" style="display:block;border:0;outline:none;text-decoration:none;height:auto;"/></a></td><td valign="middle" style="font-family:Arial,Helvetica,sans-serif;font-size:18px;font-weight:700;line-height:1.2;color:#1E335C;">NextGen CTO</td></tr></table><div style="margin:auto;text-align:center;"><p style="color:#172B4D;font-size:14px;font-weight:600;">Follow us on</p><table role="presentation" cellspacing="0" cellpadding="0" border="0" align="center" style="margin:0 auto;"><tr><td style="padding:0 6px;"><a href="https://www.instagram.com/code.with.ctobhaiya?igsh=MTgyM3ZyY2V6enJheQ==" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_a58afaf2-29b8-4761-9c0e-6d9fc6ae6f4a.png" style="width:40px;height:40px;" alt="Instagram"/></a></td><td style="padding:0 6px;"><a href="https://www.linkedin.com/in/anuj-kumar-a-k-a-cto-bhaiya-on-youtube-9a188968/" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_44a6715c-441d-43f8-b5ee-bad637d717d3.png" style="width:40px;height:40px;" alt="LinkedIn"/></a></td><td style="padding:0 6px;"><a href="https://www.youtube.com/@CodingwithCTOBhaiya" style="cursor:pointer;text-decoration:none;"><img src="https://algozenith.s3.ap-south-1.amazonaws.com/content/07-06-24/8059_11a31c49-ba39-442b-81ac-b0816e2a71a1.png" style="width:40px;height:40px;" alt="YouTube"/></a></td></tr></table></div><div style="flex-grow:1;height:1px;background-color:black;margin-top:2rem;"></div><p style="font-weight:300;margin:0;padding:0;text-align:center;font-size:15px;">If you are no longer interested, click <a href="{{unsubscribe_url}}">here</a> to unsubscribe.</p><p style="font-weight:300;margin-top:6px;text-align:center;font-size:15px;">&copy; Copyright 2025. NextGen CTO Pvt Ltd. All Rights Reserved.</p></td></tr></table></td></tr></table></body></html>$socr143_html$,
  text_template = $socr143_txt$Your roadmap for {{program_name}}

Hi {{first_name}},

Welcome to your career readiness roadmap in {{program_name}}.

You do not need to complete everything in one day.

The goal is simple:

Start step by step and keep moving with clarity.

Here is how you should approach your journey:

Start with your technical foundations.
Then move towards AI and modern development basics.
After that, focus on hands-on projects.
Then improve your Resume, GitHub, and LinkedIn.
Finally, prepare yourself for interviews with more confidence.

Do not learn randomly.

Follow the roadmap, complete your pending steps, and keep checking your progress.

Your next step is simple:

Open your dashboard.
Check your first pending task.
Start from there.

{{cta_label}}: {{cta_url}}

You can also open your dashboard here:

{{dashboard_url}}

If you need help, use the support channel here:

{{support_url}}

You are receiving this email because you are a subscriber of NextGen CTO.

Unsubscribe or manage preferences:
{{unsubscribe_url}}$socr143_txt$,
  variables = '[{"key":"email_logo_url","label":"Brand logo URL","required":false,"sample":"https://www.nextgen-cto.in/assets/logo-hd.png","inputType":"url","source":"system","helpText":"Public HTTPS URL from EMAIL_BRAND_LOGO_URL or NEXT_PUBLIC_EMAIL_BRAND_LOGO_URL."},{"key":"first_name","label":"Recipient first name","required":false,"sample":"Anuj","inputType":"text","source":"recipient"},{"key":"college_name","label":"College name","required":false,"sample":"MAIT","inputType":"text","source":"recipient"},{"key":"program_name","label":"Program name","required":true,"sample":"NextGen CTO Career Readiness Program","inputType":"text","source":"campaign"},{"key":"cta_url","label":"CTA URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"cta_label","label":"CTA button text","required":true,"sample":"View your roadmap","inputType":"text","source":"campaign"},{"key":"dashboard_url","label":"Dashboard URL","required":false,"placeholder":"https://...","inputType":"url","source":"system"},{"key":"support_url","label":"Support URL","required":true,"placeholder":"https://...","inputType":"url","source":"campaign"},{"key":"unsubscribe_url","label":"Unsubscribe URL","required":false,"inputType":"url","source":"system","helpText":"System-generated on send. Preview-only in Email Center."}]'::jsonb,
  updated_at = now()
where slug = 'student-onboarding-career-readiness-roadmap';

commit;
